package zombie.core.skinnedmodel.model;
public final class IsoObjectAnimations{private static IsoObjectAnimations instance=new IsoObjectAnimations();final java.util.ArrayList<AnimatedObject> animatedObjects=new java.util.ArrayList<>();public static int builds;public static IsoObjectAnimations getInstance(){builds++;throw new AssertionError("Native animation factory must not run");}public static void set(zombie.iso.IsoObject o,zombie.core.skinnedmodel.animation.AnimationTrack t){instance.animatedObjects.removeIf(x->x.object==o);instance.animatedObjects.add(new AnimatedObject(o,t));}public static void duplicate(zombie.iso.IsoObject o,zombie.core.skinnedmodel.animation.AnimationTrack t){instance.animatedObjects.add(new AnimatedObject(o,t));}public static void reset(){instance.animatedObjects.clear();}static final class AnimatedObject{zombie.iso.IsoObject object;zombie.core.skinnedmodel.animation.AnimationTrack track;AnimatedObject(zombie.iso.IsoObject o,zombie.core.skinnedmodel.animation.AnimationTrack t){object=o;track=t;}}}
